// ---------- конфиг варианта (TK-007): подпись, набор, стена и клетки П-05, «Подходов до» ----------
const WALL_MAIN = "возраст ≥ 45 мин, размер ≥ $10k, без порога силы";
const esc = t => String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;");
// «0,685 FAIL [0,301–0,704]» из отчёта → доли двумя знаками
const f2str = t => String(t).replace(/(\d+),(\d{3,})/g, (m, a, b) => f2(parseFloat(a + "." + b)));
const upToHead = "<thead><tr><th>подходов до</th><th colspan='3' class='sep'>август</th><th colspan='3' class='sep'>сентябрь</th></tr>" +
  "<tr><th></th>" + [0, 1].map(() => "<th class='num sep'>сделок</th><th class='num'>$</th><th class='num'>доля &gt; 5 сут</th>").join("") + "</tr></thead>";
function approachUpTo(key) {
  if (key === "btc4h_trail") {
    const B = NH && NH.approach && NH.approach.busy;
    if (!B || !B.rules_kpi) return null;
    const sh = v => v.n < 10 ? "сделок нет" : f2(v.frac_gt_5d) + (v.n < 30 ? " (описание)" : "");
    const td = v => "<td class='num sep'>" + v.n + "</td><td class='num " + cls(v.usd) + "'>" + money(v.usd) + "</td><td class='num " +
      (v.n >= 10 && v.frac_gt_5d > 0.10 ? "neg" : "") + "'>" + sh(v) + "</td>";
    const rows = B.rules_kpi.filter(r => /^все|^первые/.test(r.rule));
    return "<div class='scroll'><table>" + upToHead + "<tbody>" + rows.map(r => "<tr><td>" + (/^все/.test(r.rule) ? "все" : "≤ " + r.rule.replace("первые ", "")) + "</td>" +
      td(r.aug) + td(r.sep) + "</tr>").join("") + "</tbody></table></div><p class='note'>Пересчёт с занятостью монеты (busy-replay, T-31), $ на позицию $" +
      D.position_usd + "; 508 из 4264 сигналов без номера подхода исключены — строка «все» здесь &ne; база (сентябрь 0,31 против 0,13), сравнивать строки только между собой. " +
      "Цель — доля &le; 0,10. На проверке у Судьи.</p>";
  }
  const P7 = D.p07;
  if (key === "g85" && P7 && P7.h14) {
    const base = (P7.stage12.cells || []).find(c => c.cell === "base");
    const tdB = m => "<td class='num sep'>" + base.n[m] + "</td><td class='num " + cls(base.usd[m]) + "'>" + money(base.usd[m]) + "</td><td class='num " + (base.frac[m] > 0.10 ? "neg" : "") + "'>" + f2(base.frac[m]) + "</td>";
    const ks = P7.h14.rows.filter(r => /^k\d/.test(r[0]));
    const tdR = (r, i) => "<td class='num sep'>" + esc(r[i]) + "</td><td class='num'>" + esc(r[i + 1]) + "</td><td class='num'>" + esc(f2str(r[i + 2])) + "</td>";
    return "<div class='scroll'><table>" + upToHead + "<tbody>" + (base ? "<tr><td>все</td>" + tdB("aug") + tdB("sep") + "</tr>" : "") +
      ks.map(r => "<tr><td>≤ " + r[0].match(/^k(\d)/)[1] + "</td>" + tdR(r, 1) + tdR(r, 4) + "</tr>").join("") +
      "</tbody></table></div><p class='note'>П-07 H14 на Г-85а (последовательный проход, [интервал] — устойчивость по исключениям); " + esc(P7.h_judge.split(" (")[0]) +
      ": «не проходит» во всех клетках, случай В.</p>";
  }
  return null;
}
function renderConfig() {
  const k = state.variant, box = document.getElementById("cfg-body");
  const p05 = isP05(k), meta = VARIANT_META[k] || {};
  const sameAsMain = k === "btc4h_trail" || k === "btc4h_take" || meta.group === "p02";
  const wall = p05 ? p05Label(k.slice(4)) + "; что не названо — как у главного (" + WALL_MAIN + ")"
    : sameAsMain ? WALL_MAIN + (k === "btc4h_trail" ? "" : " (как у главного)")
    : "по набору " + (VARIANT_SET[k] || "—") + " (параметры стены набора)";
  const cells = NH ? Object.keys(NH.by_variant).filter(x => isP05(x) && NH.by_variant[x].kpi07 && P5 && P5.cells[x.slice(4)]) : [];
  const ord = v => v === "проходит" ? 0 : v === "на границе" ? 1 : 2;
  cells.sort((a, b) => ord(NH.by_variant[a].kpi07.verdict) - ord(NH.by_variant[b].kpi07.verdict));
  const chips = cells.map(x => { const g = NH.by_variant[x].kpi07;
    return "<button data-p05='" + x.slice(4) + "' aria-pressed='" + (x === k) + "'>" + p05Label(x.slice(4)) + " — <b>" + g.verdict + "</b> (авг " + f2(g.frac.aug) + " · сен " + f2(g.frac.sep) + ")</button>"; }).join("");
  const up = approachUpTo(k);
  const rows = [
    ["Вариант", esc(VARIANT_PILL[k] || k)],
    ["Описание", esc(VARIANT_FULL[k] || "—")],
    ["Набор", esc(VARIANT_SET[k] || (p05 ? VARIANT_SET.btc4h_trail + " (как у главного)" : "—"))],
    ["Стена (П-05)", esc(wall) + (P5 ? " <span class='badge warn'>" + esc(P5.status) + "</span>" : "")],
    ["Клетки П-05 с KPI", P5 ? (cells.length ? "<div class='chip-list'>" + chips + "</div><p class='note'>доля часов ожидания нового максимума &gt; 5 сут (порог 0,10), правило П-07; всего клеток сетки " +
      Object.keys(P5.cells).length + " — в свёрнутом блоке ниже; клик — вариант во всех плитках</p>" : "нет расчёта KPI") : "нет данных П-05"],
    ["Подходов до", up || "<span class='muted'>нет расчёта</span>"],
  ];
  box.innerHTML = "<dl class='cfg-grid'>" + rows.map(([t, v]) => "<dt>" + t + "</dt><dd>" + v + "</dd>").join("") + "</dl>";
  box.querySelectorAll("[data-p05]").forEach(el => el.addEventListener("click", () => pickP05(el.dataset.p05)));
}
// ---------- вкладка «Гипотезы»: номер подхода — срезы ----------
function renderApNum() {
  const box = document.getElementById("panel-apnum"), A = NH && NH.approach;
  if (!A || !A.by_number) { box.style.display = "none"; return; }
  document.getElementById("apnum-note").innerHTML = "Только главный вариант (BTC 4 ч, трейл 1/1), готовые сделки без пересчёта занятости — срез, не правило. Сделок: август " +
